                                                    proc_spo_field.gfield("option", "disabled", !that.DetailDto.Permissions?.LzeEvidovat);
                                                    c_spo_field.gfield("disable");
                                                    priz_spo_field.gfield("option", "disabled", !that.DetailDto.Permissions?.LzeEvidovat);
                                                    break;
