                    let form = $.newDiv("gform--view-mode").appendTo(this.panelInfo);
                    form.gform("setup", { layoutDescriptor: "L1M1S1, breaks-300-400" }).
                        gformsection("create").gpidbar({ pid: this.DetailDto.ixp_sml_pri });
                    let formBuilder = new Gordic.Forms.Form({ layoutDescriptor: "L1M1S1 L-8-4-0 M-8-4-0 S-12-12-0, breaks-300-400" })
                        .addSection()
                        .addRow("Datum uzavření").addField("gstaticfield", { name: "pripad" /* Gordic.Sml.Interface.GDokladSmlDtoNames.pripad */ + "." + "dat_uzavreni" /* Gordic.Sml.Interface.GPripadSmlDtoNames.dat_uzavreni */, itemTemplate: "{#:date}" })
                        .addRow("Datum platnosti").addField("gstaticfield", { name: "pripad" /* Gordic.Sml.Interface.GDokladSmlDtoNames.pripad */ + "." + "dat_platnost" /* Gordic.Sml.Interface.GPripadSmlDtoNames.dat_platnost */, itemTemplate: "{#:date}" })
                        .addRow("Datum účinnosti").addField("gstaticfield", { name: "pripad" /* Gordic.Sml.Interface.GDokladSmlDtoNames.pripad */ + "." + "dat_ucinnost" /* Gordic.Sml.Interface.GPripadSmlDtoNames.dat_ucinnost */, itemTemplate: "{#:date}" });
                    // TODO: dodělat podmínku
                    //if ((this.DetailDto.typ_dok !== Sml.Globals.Enums.TypDok.Dodatek && this.DetailDto._isFinProfil(this.DetailDto.ktg_typ)) || (this.DetailDto.typ_dok === Sml.Globals.Enums.TypDok.Dodatek && this.DetailDto._isFinProfil(this.DetailDto.ktg_typ_nad)))
                    formBuilder
                        .addSection()
                        .addRow("Počátek financování").addField("gstaticfield", { name: "pripad" /* Gordic.Sml.Interface.GDokladSmlDtoNames.pripad */ + "." + "fin_od" /* Gordic.Sml.Interface.GPripadSmlDtoNames.fin_od */ })
                        .addRow("Konec financování").addField("gstaticfield", { name: "pripad" /* Gordic.Sml.Interface.GDokladSmlDtoNames.pripad */ + "." + "fin_do" /* Gordic.Sml.Interface.GPripadSmlDtoNames.fin_do */ });
                    formBuilder
                        .addSection()
                        .addRow("Cena").addField("gstaticfield", { name: "pripad" /* Gordic.Sml.Interface.GDokladSmlDtoNames.pripad */ + "." + "c_mena_doc" /* Gordic.Sml.Interface.GPripadSmlDtoNames.c_mena_doc */, itemTemplate: "{#:number(C2)}" })
                        .addRow("Celková částka").addField("gstaticfield", { name: "pripad" /* Gordic.Sml.Interface.GDokladSmlDtoNames.pripad */ + "." + "c_mena" /* Gordic.Sml.Interface.GPripadSmlDtoNames.c_mena */, itemTemplate: "{#:number(C2)}" })
                        .addRow("Rozpis na roky").addField("gstaticfield", { name: "pripad" /* Gordic.Sml.Interface.GDokladSmlDtoNames.pripad */ + "." + "c" /* Gordic.Sml.Interface.GPripadSmlDtoNames.c */, itemTemplate: "{#:number(C2)}" })
                        .addRow("Položky FP").addField("gstaticfield", { name: "pripad" /* Gordic.Sml.Interface.GDokladSmlDtoNames.pripad */ + "." + "c_pol" /* Gordic.Sml.Interface.GPripadSmlDtoNames.c_pol */, itemTemplate: "{#:number(C2)}" })
                        .addRow("Počet položek FP").addField("gstaticfield", { name: "pripad" /* Gordic.Sml.Interface.GDokladSmlDtoNames.pripad */ + "." + "num_pol" /* Gordic.Sml.Interface.GPripadSmlDtoNames.num_pol */ })
                        .addSection()
                        .addRow("Stav").addField("gstaticfield", { name: "pripad" /* Gordic.Sml.Interface.GDokladSmlDtoNames.pripad */ + "." + "sml_stav_txt" /* Gordic.Sml.Interface.GPripadSmlDtoNames.sml_stav_txt */ });
                    // vytvoření formuláře a naplnění dat
                    form.gform("createFrom", formBuilder).findFields().gfield("model", "apply", this.DetailDto);
                    this.panelInfo.trigger("resize").find(".gform-section").children("label").first().addClass("g-state-text g-state-active");
