                /**
                 * Zobrazení položek věcného profilu
                 *
                 * @returns {JQuery.Promise<any>} promise s operací
                 */
                polozkyVP() {
                    let that = this;
                    let visitor = new Gordic.Sml.WebClient.GSmlVecnyProfilVisitor({
                        dao: new Gordic.Sml.WebClient.GVecnyProfilSmlDAO({ ixp: this.DetailDto?.ixp }),
                        ixp: this.DetailDto?.ixp,
                        // TODO: dořešit plné načtení DetailDto a strukturu dat potřebnou pro věcný profil
                        smlpid_p: this.DetailDto ?? {}
                    });
                    let cnt = this.navigate([Gordic.Eko.WebClient.GVecnyProfilSeznam, {}]);
                    const vpContent = $.content(cnt);
                    vpContent.readyAwait.then(() => {
                        vpContent.accept(visitor);
                        vpContent.init();
                    });
                    cnt.on("closed", (ev, changed) => {
                        if (changed) {
                            that.setActiveOperationAndReloadData();
                        }
                    });
                    return cnt.promise();
                }
