                /**
                 * Zobrazení dialogu pro vytvoření kopie dokladu
                 *
                 * @returns
                 */
                vytvoreniKopie() {
                    return Sml.Dialogs.GSmlMakeCopyDlg({
                        parentContent: this,
                        opt: {
                            smlpid: this.DetailDto ?? {}
                        },
                        ModOtevreni: Gordic.Global.Enums.ModOtevreni.showModalWindow
                    }).then((ctx) => {
                        if (ctx?.ixp) {
                            const cnt = this;
                            return cnt.isl.DokladSml.read({ ixp: ctx.ixp })
                                .getData()
                                .then(function (data) {
                                if (data?.ixp_den) {
                                    let newGpc = Gordic.Eko.Utils.createBookGpc(cnt.gpc, data.ixp_den);
                                    let detailID = WebClient.SmlGrid.getDetailId(data, { ktg_typ: data.ktg_typ_nad_pr ?? data.ktg_typ_nad });
                                    cnt.navigate(["Gordic.Sml.WebClient.G" + detailID, { gpc: newGpc }], {
                                        ID: detailID + '#',
                                        Ixp: ctx.ixp,
                                        // TODO: je potřeba IxpDen, když je to v gpc?
                                        IxpDen: data.ixp_den
                                    });
                                    return $.Deferred().resolve(true).promise();
                                }
                                else
                                    return $.Deferred().resolve(false).promise();
                            });
                        }
                    });
                }
