                detailNavazaneho() {
                    return this.detailDokladu(this.$gridNavazaneDoklady);
                }
                detailDokladu($grid) {
                    let that = this;
                    let aktRadek = Gordic.Eko.Grid.currentRow($grid);
                    if (aktRadek?.ixp) {
                        // příznak aktivní operace
                        let needRefresh = false;
                        // otevření detailu
                        let detailID = WebClient.SmlGrid.getDetailId(aktRadek, this.DetailDto);
                        // TODO: zatím je zakomentován posun po řádku - pokud by se povolil, musel bych řešit na detailu případu posun po různých typech seznamů
                        let $detailWindow = this.navigate(["Gordic.Sml.WebClient.G" + detailID, { gpc: Gordic.Eko.Utils.createBookGpc(this.gpc, aktRadek.ixp_den) /*, gridRemoteControl: new Gordic.Components.GridRC(that.$gridSoupisky)*/ }], {
                            ID: detailID + '#',
                            Ixp: aktRadek.ixp,
                            // TODO: je potřeba IxpDen, když je to v gpc?
                            IxpDen: aktRadek.ixp_den
                        });
                        // obsluha aktivní operace na detailu
                        $.content($detailWindow).on(WebClient.SmlDetail.triggerChange, (retVal) => {
                            // záznam byl změně, musí se načíst znovu
                            if (retVal?.data?.ixp) {
                                // bude se občerstvovat
                                needRefresh = true;
                            }
                        });
                        // obsluha ukončení okna
                        $detailWindow.on("closed", (retVal) => {
                            // aktualizace detailu (byla-li aktivní operace v otevřeném detailu)
                            if (needRefresh) {
                                that.setActiveOperationAndReloadData();
                            }
                        });
                        return $detailWindow.createDialogPromise();
                    }
                    else
                        return $.Deferred().reject().promise();
                }
