                makeEnablePlatnost(typPlatnost) {
                    if (typPlatnost != null) {
                        // pokud je Typ cena = Volná, nelze nastavit Typ platnosti do vyčerpání částky
                        const typCeny = this.getCurrentValueNumber("typ_ceny" /* Sml.Interface.GDokladSmlDtoNames.typ_ceny */, true);
                        if (typCeny === Sml.Globals.Enums.TypCeny.Volna && typPlatnost === Sml.Globals.Enums.TypPlatnosti.DoVycerpaniCastky) {
                            // nepřípustná změna
                            this.saveChangedValues({ typ_platnost: this.DetailDto.typ_platnost });
                            this.findFields("typ_platnost" /* Sml.Interface.GDokladSmlDtoNames.typ_platnost */).gfield("model", "apply", { typ_platnost: this.DetailDto.typ_platnost });
                            throw new GError("Nepřípustná hodnota typu platnosti vůči typu ceny");
                            //return false;
                        }
                        // nuluju datum platnosti
                        this.saveChangedValues({ dat_platnost: null });
                        this.findFields("dat_platnost" /* Sml.Interface.GDokladSmlDtoNames.dat_platnost */).gfield("model", "apply", { dat_platnost: null });
                        //Call SalSendMsg(dfDatPlatnost, GM_NoEdit, 0, 0)
                        //Call SalSendMsg(dfNumRok, GM_NoEdit, 0, 0)
                        // řízení na základě typ platnosti
                        this.setEnablePlatnost(typPlatnost, true);
                        //
                        //Call SalSendMsg(dfDatPlatnost, GM_Edit, 0, 0)
                        //Call SalSendMsg(dfNumRok, GM_Edit, 0, 0)
                    }
                }
                /**
                 * Validátor pro datumy starší než rok 1900
                 *
                 * @returns {Gordic.Validators.Base} validátor
                 */
                validateDat1900() {
                    return new Gordic.Validators.Base({
                        stopping: true,
                        message: "jres:24100068", //RC 24100068 : Nepřípustná hodnota roku
                        validate: (value, source) => {
                            // kontrola na rok min. 1900
                            if (value != null && parseDate(value).getFullYear() < 1900)
                                return false;
                            else
                                return true;
                        }
                    });
                }
                /**
                 * Nastavení prvků na tabu subjektů
                 */
                enableSubjekty() {
                    // TODO: dočesat
                    let aktRadek = null;
                    if (this.$gridSubjekty)
                        aktRadek = Gordic.Eko.Grid.currentRow(this.$gridSubjekty);
                    let permEditace = WebClient.SmlDetail.getEditPermission();
                    const acts = this.actions;
                    const perms = this.DetailDto.Permissions;
                    const permsS = aktRadek?.Permissions;
                    const gridEdit = (this.$gridSubjekty?.find(".row.editing")?.length ?? 0) > 0;
                    const permJinyDoklad = this.Ixp !== aktRadek?.ixp ? { value: false, message: "Nelze měnit subjekt na jiném dokladu" } : { value: true };
                    acts.actDetailSubjektu.updatePermission(WebClient.SmlGrid.getCombinedGridPermission(aktRadek, this.Editace || gridEdit, perms?.LzeZobrazit));
                    acts.actNovySubjekt.updatePermission((this.Editace || gridEdit ? permEditace : (perms ? perms.LzePridatSubjekt : undefined)));
                    acts.actEditaceSubjektu.updatePermission(WebClient.SmlGrid.getCombinedGridPermission(aktRadek, this.Editace || gridEdit, perms?.LzeEditovatSubjekt, permsS?.LzeEditovatSubjekt, permJinyDoklad));
                    acts.actOdstraneniSubjektu.updatePermission(WebClient.SmlGrid.getCombinedGridPermission(aktRadek, this.Editace || gridEdit, perms?.LzeOdstranitSubjekt, permsS?.LzeOdstranitSubjekt, permJinyDoklad));
                    acts.actZmenaSubjektuNaPrimarni.updatePermission(WebClient.SmlGrid.getCombinedGridPermission(aktRadek, this.Editace || gridEdit, perms?.LzeEditovatSubjekt, permsS?.LzeZmenitSubjektNaPrimarni, permJinyDoklad));
                    // TODO: nemělo by jít, pokud se v gridu edituje
                    acts.actAktivniSubjekty.updatePermission(this.Editace || gridEdit ? permEditace : { value: true });
                    acts.actSubjektyZaDoklad.updatePermission(this.Editace || gridEdit ? permEditace : { value: true });
                }
