                /**
                 * Zadání parametrů tisku
                 *
                 * @param {IGPrintActionReportStarting} rep parametry tisku
                 */
                reportStarting(rep) {
                    // pouze PID, nic jiného se nepředává
                    rep.params.X0006 = this.Ixp;
                }
                // TODO: nezačne se znovu používat tato metoda? zkonzultovat s Vlastou, jak dělat reload - Vlasta doporučuje udělat load celého okna, ale šlo by nastavit nějaký příznak, že data jsou už načtená a v C# je pak nenačítat. Poslán dotaz Alíkovi, jestli mají nebo nemají aktivní ISLové operace vracet aktuální data a pak to rozhodnout
                /**
                 * Nastaví příznak aktivní operace a znovu načte celý formulář
                 *
                 * @param {boolean} withoutReload (default = false) true = neaktualizovat formulář
                 * @returns {JQuery.Promise<any>} promise
                 */
                setActiveOperationAndReloadData(withoutReload = false, retData = undefined) {
                    // vyvolání trigger o aktivní operaci
                    this.trigger(WebClient.SmlDetail.triggerChange, [{ data: this.DetailDto }]);
                    // aktualizace detailu
                    if (!withoutReload) {
                        this.element.trigger("rememberinitialopen");
                        // TODO: touhle cestou se nevrátí retData
                        return this.load();
                    }
                    else
                        return $.Deferred().resolve(retData).promise();
                }
                /**
                 * Znovu načte celý formulář
                 *
                 * @returns {JQuery.Promise<any>} promise
                 */
                reloadData() {
                    this.element.trigger("rememberinitialopen");
                    // TODO: touhle cestou se nevrátí retData
                    return this.load();
                }
