                    if (!nepovolenaZmena && (currentValues.JePodany || currentValues.JeEvidovany)) {
                        // z dodatku na jiný typ
                        if (currentValues.ktg_typ === Sml.Globals.Enums.KtgTyp.DodatekSmlouvy && newValues.ktg_typ !== Sml.Globals.Enums.KtgTyp.DodatekSmlouvy && currentValues.ac_sml != null && currentValues.ac_sml != "") {
                            // TODO: jsou všechny hodnoty vůbec vidět?
                            this.findFields("ac_sml", "ixp_doklad_nad" /*ixp_sml*/, "ac_nad", "ac_sml_nad").gfield("model", "apply", { ac_sml: null, ixp_doklad_nad /*ixp_sml*/: null, ac_nad: null, ac_sml_nad: null });
                        }
                        // změna na dodatek
                        else if (currentValues.ktg_typ !== Sml.Globals.Enums.KtgTyp.DodatekSmlouvy && newValues.ktg_typ === Sml.Globals.Enums.KtgTyp.DodatekSmlouvy) {
                            // TODO: jsou všechny hodnoty vůbec vidět?
                            this.findFields("ac_sml").gfield("model", "apply", { ac_sml: null });
                        }
                    }
                    // uložení změněných hodnot
                    if (!nepovolenaZmena) {
                        // zapamatování změněných hodnot
                        this.saveChangedValues(newValues);
                    }
