                        WebClient.SmlDetail.visibleGrpAndTab(this, newValues.JeRamcovaSmlouva, "grpNavazaneNaRS", "tabNavazaneNaRS");
                        WebClient.SmlDetail.visibleGrpAndTab(this, newValues.JeSmlouva && !newValues.JeRamcovaSmlouva, "grpObjednavky", "tabObjednavky");
