                zmenaPopis(popis) {
                    const curNazev = this.getCurrentValueString("nazev" /* Sml.Interface.GDokladSmlDtoNames.nazev */, true, true);
                    if (popis && (curNazev == null || curNazev == "")) {
                        this.findFields("nazev" /* Sml.Interface.GDokladSmlDtoNames.nazev */).gfield("model", "apply", { nazev: popis });
                    }
                }
