                                                // 348.21 01.04.04 - pamatuju si ixp_nab
                                                newValues.ixp_nab = data.ixp_nab;
                                                // 524.21 20.02.24 pro RZA je významové por_cisl_nab; Pro agendu RZA sloupec obsahuje identifikátor externího subjektu a výnamová je kombinace ixs_pri + ixs_esu + por_cis_nab s tím,
                                                newValues.por_cislo_nab = data.por_cis_nab;
                                                // 342.55 09.01.02 - predestinace BÚ
