                                                //Call pb_esu_ir._getIRInfo(smlpid.ixs_esu, smlpid.ico_esu, smlpid.rc_esu)
                                                // 376.2 18.09.15 obsluha stavu ověření ESU v ISZR
                                                //Set smlpid.stupen_ver = l_exe.n1
                                                //Call pic_esu_iszr._setIStupenVer(smlpid.ixs_esu, smlpid.stupen_ver, smlpid.ixp)
                                                // 378.12 20.06.17 GDPR
                                                //Set smlpid.typ_esu = l_exe.n2
