                    //let cMenaDoc = new Decimal(0);
                    let currCMena = this.getCurrentValueDecimal("c_mena" /* Sml.Interface.GDokladSmlDtoNames.c_mena */, true) ?? new Decimal(0.0);
                    let currTypDok = this.getCurrentValueNumber("typ_dok" /* Sml.Interface.GDokladSmlDtoNames.typ_dok */, true);
