                        let currCisloDod = this.getCurrentValueNumber("cislo_dod" /* Sml.Interface.GDokladSmlDtoNames.cislo_dod */, true);
                        return this.isl.DokladSml.zjistiCenuDokladuDodatku({ ixpSmlPri: this.DetailDto.ixp_sml_pri ?? "", cisloDod: currCisloDod ?? 0, cMena: currCMena })
