                    if (this.DetailDto.ixs_esu != null && this.DetailDto.ixs_esu == Sml.Globals.Enums.Nulak.Esu)
                        data.ixs_esu = null;
                    // naplnění políček
                    // TODO: nechat DetailDto nebo to přejmenovat zpátky na model? nějak to dořešit, v kódu totiž používám oboje
                    this.findFields()
                        .gfield("model", "apply", /*this.DetailDto*/ data, { initialValues: true })
                        .gfield("model", "validators", this.validators);
                    // TODO: povoleno i pro jen podané doklady
                    if (true /*(!this.DetailDto?.JePodany || this.DetailDto?.JeVJineAgende)*/) {
                        // naplnění popisných vlastností
                        // TODO: nebo to dělat přes pole?
                        Gordic.PopisneVlastnosti.applyValues(this, /*this.DetailDto*/ data.vlastnosti);
                    }
                    // nastavení prvků
                    this.setLabel();
                    // TODO: tohle asi ne, defaultně by se měl form nastavit podle aktuálních hodnot v DTO
                    //this.setEnableFieldTypDok(true);
                    this.showMatchingSubject(/*this.DetailDto*/ data?.ac_ver_zak);
                    // aktualizace informací na tabgrupě financování
                    this.updateInfoUFinancovani(/*this.DetailDto*/ data?.c_mena_doc, /*this.DetailDto*/ data?.dat_platnost, /*this.DetailDto*/ data?.dat_ucinnost);
                    // badge
                    // TODO: nechat to zde nebo to přesunout do metody enable?
                    WebClient.SmlDetail.updateBadge(this.BadgeSubjekty, /*this.DetailDto*/ data?.pocet_subjektu);
                    //SmlDetail.updateBadge(this.BadgeNavazaneNaRS, this.DetailDto?.num_smlrs_bnd);
                    //SmlDetail.updateBadge(this.BadgeObjednavky, this.DetailDto?.num_obj);
                    WebClient.SmlDetail.updateBadge(this.BadgeNavazane, ( /*this.DetailDto*/data?.num_dod ?? 0) + ( /*this.DetailDto*/data?.num_nav_dok ?? 0));
                    WebClient.SmlDetail.updateBadge(this.BadgeDodatky, /*this.DetailDto*/ data?.num_dod);
                    WebClient.SmlDetail.updateBadge(this.BadgeNavazaneDoklady, /*this.DetailDto*/ data?.num_nav_dok);
