                    //    action: new GAction(Gordic.Prefabs.Actions.UlozitDoClipboardu({
                    //        inputData: (action, event, context, customData) => {
                    //            const deferred = $.Deferred();
                    //            if (event?.currentTarget) {
                    //                const field = $.content(event.currentTarget as HTMLElement).findFields(fieldOptions.name ? fieldOptions.name : "");
                    //                const text = field.gfield<Sml.Interface.GDokladSmlDto>('getValue');
                    //                deferred.resolve(text?.ixp);
                    //            }
